"""Static guards for packaged failures; Unreal runtime validation is still required."""
from pathlib import Path
import re
import unittest


ROOT = Path(__file__).resolve().parents[1]


class PackagedRegressionTests(unittest.TestCase):
    def test_score_tracker_is_a_gc_traced_strong_reference(self) -> None:
        header = (ROOT / "Source/PixelArena/ArenaGameMode.h").read_text()
        self.assertRegex(
            header,
            r"UPROPERTY\(\)\s+TObjectPtr<UArenaScoreTracker>\s+ScoreTracker\b",
        )

    def test_dynamic_palette_directory_is_cooked(self) -> None:
        config = (ROOT / "Config/DefaultGame.ini").read_text()
        section = config.split("[/Script/UnrealEd.ProjectPackagingSettings]", 1)[1]
        section = section.split("\n[", 1)[0]
        source = (ROOT / "Source/PixelArena/ArenaGameMode.cpp").read_text()
        asset_path = re.search(r'LoadObject<UArenaPalette>\(nullptr, TEXT\("([^"]+)"\)', source)
        self.assertIsNotNone(asset_path)
        directory = asset_path.group(1).rsplit("/", 1)[0]
        self.assertIn(f'+DirectoriesToAlwaysCook=(Path="{directory}")', section)


if __name__ == "__main__":
    unittest.main()


